class BandpowerWorker(QThread):
    finished = pyqtSignal()
    progress = pyqtSignal(int)
    error = pyqtSignal(str)

    def __init__(self, raw, channels, bands, result_path):
        super().__init__()
        self.raw = raw
        self.channels = channels
        self.bands = bands
        self.result_path = result_path

    def run(self):
        try:
            from LFP_EEG_analyser.LFP_EEG_analyser.bandpower_analysis import calculate_bandpower
            total_steps = len(self.channels) * len(self.bands)
            current_step = 0
            
            def progress_callback(step):
                nonlocal current_step
                current_step += 1
                progress = int((current_step / total_steps) * 100)
                self.progress.emit(progress)
            
            calculate_bandpower(
                self.raw, 
                self.channels, 
                self.bands, 
                self.result_path, 
                progress_callback=progress_callback
            )
            self.finished.emit()
        except Exception as e:
            self.error.emit(str(e))

