    def import_raw(self,raw):
        self.raw = raw
        self.raw_processed = self.raw.copy()

    def showChannel(self):
        layout = QtWidgets.QVBoxLayout(self.scrollAreaWidgetContents_2)  
        channel_names = self.raw.info['ch_names']  
        self.channel_checkboxes = []
        for channel_name in channel_names:
            checkbox = QtWidgets.QCheckBox(channel_name)  
            checkbox.setObjectName(channel_name)
            layout.addWidget(checkbox)
            self.channel_checkboxes.append(checkbox)

        all_checkbox = QtWidgets.QCheckBox("All")
        all_checkbox.setObjectName("All")
        layout.addWidget(all_checkbox)
        all_checkbox.toggled.connect(self.toggle_all_checkboxes)
        self.all_checkbox = all_checkbox

        self.scrollAreaWidgetContents_2.setLayout(layout)  
        self.scrollArea.setWidget(self.scrollAreaWidgetContents_2)

    def toggle_all_checkboxes(self,state):
        for checkBox in self.channel_checkboxes:
            pattern = "ACC.*"
            if not re.search(pattern,checkBox.objectName()):
                checkBox.setChecked(state)

    def set_freq_bands(self):
        # 初始化字典
        self.freq_bands = {'Delta': None, 'Theta': None, 'Alpha': None, 'Beta': None, 'Gamma': None}

        # 为每个频带设置值
        band_configs = {
            'Delta': (self.radioButton_1, self.Del_1, self.Del_2),
            'Theta': (self.radioButton_2, self.The_1, self.The_2),
            'Alpha': (self.radioButton_3, self.Alp_1, self.Alp_2),
            'Beta':  (self.radioButton_4, self.Bet_1, self.Bet_2),
            'Gamma': (self.radioButton_5, self.Gam_1, self.Gam_2),
            'other': (self.radioButton_6, self.Oth_1, self.Oth_2)
        }

        for band, (checkbox, line_edit1, line_edit2) in band_configs.items():
            if checkbox.isChecked():
                val1 = line_edit1.text()
                val2 = line_edit2.text()

                # 检查输入是否为空
                if val1.strip() == '' or val2.strip() == '':
                    self.freq_bands[band] = None
                else:
                    try:
                        # 将文本转换为浮点数
                        num1 = float(val1)
                        num2 = float(val2)
                        if num1 >= num2:
                            raise ValueError("The first value must be less than the second value.")
                        self.freq_bands[band] = (num1, num2)
                    except ValueError as e:
                        # 弹出错误提示窗口
                        QtWidgets.QMessageBox.critical(None, 'Input Error', f'Error in {band} band: {str(e)}')
                        return

    def set_channels(self):
        self.selected_channels = []
        for checkbox in self.scrollAreaWidgetContents_2.findChildren(QtWidgets.QCheckBox):
            if checkbox.isChecked() and checkbox.objectName()!= 'All':
                self.selected_channels.append(checkbox.text())

    def connect_actions(self):
        self.pushButton_cancel.clicked.connect(self.win.close)
        self.pushButton_ok.clicked.connect(self.apply_config)
        self.pushButton_ok.clicked.connect(self.win.close)

    def apply_config(self):
        self.set_freq_bands()
        self.set_channels()
        print(self.freq_bands)

        filtered_bands = {band: ranges for band, ranges in self.freq_bands.items() if ranges is not None}
        
        if self.title_1.text() == 'Band Power':
            import os
            result_path = os.path.join(self.raw.info['description'],'Bandpower')
            os.makedirs(result_path, exist_ok=True)

            self.dialog = QProgressDialog("Processing...", "Abort", 0, 100, self.win)
            self.dialog.setWindowTitle("Please Wait")
            self.dialog.setModal(True)
            self.dialog.resize(600,400)
            self.dialog.show()

            # Create and start worker thread
            self.worker = BandpowerWorker(self.raw, self.selected_channels, filtered_bands, result_path)
            self.worker.finished.connect(self.on_calculation_complete)
            self.worker.progress.connect(self.dialog.setValue)  # Connect progress signal
            self.worker.error.connect(self.on_calculation_error)
            self.dialog.canceled.connect(self.worker.terminate)  # Add cancel functionality
            self.worker.start()
        else:
            import os
            result_path = os.path.join(self.raw.info['description'],'FilterPlot')
            os.makedirs(result_path, exist_ok=True)        

            self.dialog = QProgressDialog("Processing...", "Abort", 0, 100, self.win)
            self.dialog.setWindowTitle("Please Wait")
            self.dialog.setModal(True)
            self.dialog.resize(600,400)
            self.dialog.show()

            # Create and start worker thread
            self.worker = FilterPlotWorker(self.raw, self.selected_channels, filtered_bands, result_path)
            self.worker.finished.connect(self.on_calculation_complete)
            self.worker.progress.connect(self.dialog.setValue)  # Connect progress signal
            self.worker.error.connect(self.on_calculation_error)
            self.dialog.canceled.connect(self.worker.terminate)  # Add cancel functionality
            self.worker.start()

    def on_calculation_complete(self):
        self.dialog.close()
        QMessageBox.information(self.win, "Finish", "Successfully", QMessageBox.Ok)
        self.win.close()

    def on_calculation_error(self, error_message):
        self.dialog.close()
        QMessageBox.critical(self.win, "Error", f"An error occurred: {error_message}", QMessageBox.Ok)

